def maybe_request_session(output: Path, request: dict[str, Any]) -> dict[str, Any] | None:
    """Route an ordinary CKB CLI query through an already activated session."""

    if os.environ.get("CKB_STDIO_FALLBACK") == "1":
        return None
    identity = environment_session()
    if identity is None:
        return None
    harness, session_id, parent_pid = identity
    if not _activation_exists(output.resolve(), harness, session_id):
        return None
    return request_session(
        harness=harness,
        session_id=session_id,
        output=output,
        request=request,
        parent_pid=parent_pid,
    )

def list_sessions(*, root: Path | None = None, active_only: bool = False) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    leases: list[dict[str, Any]] = []
    if root_value.is_dir():
        for path in sorted(root_value.glob("stdio-*/lease.json")):
            lease = _read_json(path)
            if not lease:
                continue
            active = lease.get("state") in {"starting", "ready", "closing"} and pid_exists(lease.get("supervisor_pid"))
            if active_only and not active:
                continue
            value = dict(lease)
            value["active"] = active
            leases.append(value)
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed",
        "root": str(root_value),
        "count": len(leases),
        "active": sum(1 for item in leases if item["active"]),
        "leases": leases,
    }

def cleanup_sessions(*, root: Path | None = None, only_key: str | None = None) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    cleaned: list[dict[str, Any]] = []
    if not root_value.is_dir():
        return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": []}
    directories = [root_value / only_key] if only_key else sorted(path for path in root_value.glob("stdio-*") if path.is_dir())
    for directory in directories:
        lease = _read_json(_lease_path(directory))
        if not lease:
            continue
        supervisor_pid = lease.get("supervisor_pid")
        server_pid = lease.get("server_pid")
        parent_pid = lease.get("parent_pid")
        parent_dead = bool(parent_pid) and not pid_exists(parent_pid)
        supervisor_dead = bool(supervisor_pid) and not pid_exists(supervisor_pid)
        if lease.get("state") in {"starting", "ready", "closing"} and pid_exists(supervisor_pid) and parent_dead:
            json_write(directory / "control" / f"c-{uuid.uuid4().hex[:12]}.json", {"reason": "parent-death-cleanup"})
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "close-requested"})
            continue
        if (supervisor_dead or not supervisor_pid) and lease.get("state") in {"fallback", "closed"}:
            deadline = time.monotonic() + 1.5
            while pid_exists(server_pid) and time.monotonic() < deadline:
                time.sleep(POLL_SECONDS)
            forced = False
            if pid_exists(server_pid):
                forced = _force_terminate_pid(int(server_pid))
            lease.update(
                {
                    "state": "closed",
                    "supervisor_pid": None,
                    "server_pid": None,
                    "closed_at_utc": lease.get("closed_at_utc") or utc_now(),
                    "close_reason": lease.get("close_reason") or "stale-cleanup",
                    "object_counts": _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0),
                }
            )
            _write_lease(directory, lease)
            _clear_transient(directory)
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "stale-cleaned", "forced_server": forced})
    return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": cleaned}

def audit_sessions(*, root: Path | None = None) -> dict[str, Any]:
    listing = list_sessions(root=root)
    errors: list[str] = []
    totals = _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0)
    for lease in listing["leases"]:
        serialized = json.dumps(lease, ensure_ascii=False, sort_keys=True).casefold()
        for field in _FORBIDDEN_STATE_KEYS:
            if f'"{field}"' in serialized:
                errors.append(f"forbidden-state-field:{field}:{lease.get('lifecycle_key')}")
        counts = lease.get("object_counts") or {}
        if lease.get("active"):
            for name in totals:
                totals[name] += int(counts.get(name, 0))
        elif lease.get("state") == "closed" and any(int(counts.get(name, 0)) for name in totals):
            errors.append(f"closed-object-count:{lease.get('lifecycle_key')}")
        if lease.get("state") == "ready" and not pid_exists(lease.get("server_pid")):
            errors.append(f"ready-server-missing:{lease.get('lifecycle_key')}")
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "root": listing["root"],
        "active": listing["active"],
        "object_counts": totals,
        "errors": errors,
    }

def _integer(value: Any, name: str, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise CkbError(f"stdio request {name} must be an integer in [{minimum}, {maximum}]")
    return value

def _utf8_safe(value: str) -> str:
    """Replace lone UTF-16 surrogate code points before UTF-8 consumers see them."""
    return "".join("\ufffd" if 0xD800 <= ord(character) <= 0xDFFF else character for character in value)

def _required_text(request: dict[str, Any], name: str, maximum: int) -> str:
    value = request.get(name)
    if not isinstance(value, str) or not value.strip():
        raise CkbError(f"stdio record-explanation {name} must be a non-empty string")
    value = _utf8_safe(value).strip()
    if len(value) > maximum:
        raise CkbError(f"stdio record-explanation {name} exceeds {maximum} characters")
    return value

def refresh_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    if not markdown.is_dir() or not human.is_dir():
        raise CkbError("work record navigation requires human and markdown roots")
    text, records = render_work_record_index(markdown)
    for root in (markdown, human):
        (root / WORK_RECORD_INDEX).write_text(text, encoding="utf-8", newline="\n")
    audit = audit_work_record_index(output)
    json_write(output / "workspace-meta/work-record-index-audit.json", audit)
    if audit["status"] != "passed":
        raise CkbError(f"work record navigation audit failed: {audit['errors'][:10]}")
    return {"status": "passed", "record_count": len(records), "audit": audit}

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def validate_core_boundary() -> None:
    lite = {path.relative_to(ROOT).as_posix() for path in source_files(False)}
    full = {path.relative_to(ROOT).as_posix() for path in source_files(True)}
    missing = sorted(set(CORE_REQUIRED_FILES) - lite)
    if missing:
        raise RuntimeError(f"lite core capability files are absent: {missing}")
    if any(path == "plugins" or path.startswith("plugins/") for path in lite | full):
        raise RuntimeError("core distributions must not contain plugins/")
    if not lite < full:
        raise RuntimeError("full-win-x64 must strictly extend lite")
    unexpected = sorted(
        path for path in full - lite
        if not path.startswith("assets/runtime/win-x64/")
    )
    if unexpected:
        raise RuntimeError(f"full-win-x64 adds non-runtime files: {unexpected}")

def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path

def validate_plugin_dist() -> tuple[str, list[Path], dict]:
    dist = PLUGIN_ROOT / "dist"
    files = [dist / name for name in PLUGIN_FILES]
    missing = [path.name for path in files if not path.is_file() or path.stat().st_size == 0]
    if missing:
        raise RuntimeError(f"Obsidian plugin dist files are absent: {missing}")
    manifest = json.loads((dist / "manifest.json").read_text(encoding="utf-8"))
    version = manifest.get("version")
    if not isinstance(version, str) or not version.strip():
        raise RuntimeError("Obsidian plugin version is absent from manifest.json")
    build_record = json.loads((dist / "build-record.json").read_text(encoding="utf-8"))
    if build_record.get("status") != "passed":
        raise RuntimeError("Obsidian plugin build-record.json has not passed")
    recorded = {item["path"]: item for item in build_record.get("files", [])}
    for path in files:
        if path.name == "build-record.json":
            continue
        item = recorded.get(path.name)
        if not item:
            raise RuntimeError(f"Obsidian plugin build record is missing: {path.name}")
        if int(item.get("size", -1)) != path.stat().st_size or item.get("sha256") != sha256(path):
            raise RuntimeError(f"Obsidian plugin dist differs from build record: {path.name}")
    return version, files, build_record

def build_plugin(dist: Path) -> dict:
    version, files, build_record = validate_plugin_dist()
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder-obsidian",
        "version": version,
        "distribution": "obsidian-plugin",
        "category": "plugin",
        "requires": {
            "knowledge_base": "CKB output with machine/knowledge.sqlite",
            "core_package": "installed separately",
        },
        "bundled_core": False,
        "bundled_offline_runtime": False,
        "agent_deploy": {
            "standalone": "python deploy.py deploy --vault VAULT",
            "core": "ckb.py obsidian-plugin register/deploy/status/remove",
            "auto_deploy_after_registration": True,
        },
        "files": [
            {"path": path.name, "size": path.stat().st_size, "sha256": sha256(path)}
            for path in files
        ],
        "upstream_commit": build_record.get("claudian_commit"),
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-obsidian-{version}.zip"
    if archive_path.exists():
        archive_path.unlink()
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            info = zipfile.ZipInfo(path.name, date_time=(2026, 8, 30, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"Obsidian plugin ZIP CRC failed: {bad_member}")
        if archive.namelist() != list(PLUGIN_FILES):
            raise RuntimeError("Obsidian plugin ZIP member set or order differs")
        for path in files:
            if archive.read(path.name) != path.read_bytes():
                raise RuntimeError(f"Obsidian plugin ZIP bytes differ: {path.name}")
    result = {
        "status": "passed",
        "distribution": "obsidian-plugin",
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-obsidian-{version}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result

def build(kind: str, dist: Path) -> dict:
    if kind == "obsidian-plugin":
        return build_plugin(dist)
    return build_core(kind, dist)

def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--kind",
        choices=("lite", "full-win-x64", "obsidian-plugin", "both", "all"),
        required=True,
    )
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    if args.kind == "both":
        kinds = ("lite", "full-win-x64")
    elif args.kind == "all":
        kinds = ("lite", "full-win-x64", "obsidian-plugin")
    else:
        kinds = (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0
